(() => {
  const low = c => String(c.frase || "").toLocaleLowerCase("de");
  const add = (topic, ficha) => { GRAMATICA.push(topic); GRAM_FICHAS[topic.id] = ficha; };

  add({id: "verbpaare", title: "Pôr × estar: legen/liegen, stellen/stehen, setzen/sitzen", short: "Pôr (movimento, objeto no acusativo): legen, stellen, setzen, hängen. Estar (lugar, sem objeto): liegen, stehen, sitzen, hängen.",
    body: ["Os verbos de pôr são regulares e têm objeto: Ich lege das Buch… Os de estar são irregulares e não têm objeto: Das Buch liegt…",
      "Deitado/plano: legen/liegen. Em pé: stellen/stehen. Sentado: setzen/sitzen (sich setzen = sentar-se)."],
    trap: ["Ich liege das Buch auf den Tisch.", "Ich lege das Buch auf den Tisch."],
    examples: [["Ich stelle die Flasche in den Kühlschrank.", "Ponho a garrafa na geladeira."], ["Die Flasche steht im Kühlschrank.", "A garrafa está na geladeira."]],
    detect: c => /\b(lege|legst|legt|gelegt|stelle|stellst|stellt|gestellt|setze|setzt|gesetzt|sitze|sitzt|gesessen|liege|liegst|liegt|gelegen)\b/.test(low(c))}, {
    ideia: "O alemão tem um verbo para PÔR (com movimento) e outro para ESTAR (parado), conforme a posição: deitado, em pé, sentado ou pendurado.",
    macete: "Pôr = verbo regular com -e- (legen, stellen, setzen) + acusativo. Estar = irregular com -i-/-ie- (liegen, stehen, sitzen) + dativo.",
    visual: {head: ["posição", "PÔR (Wohin? + acus.)", "ESTAR (Wo? + dat.)"], rows: [["deitado / plano", "[legen] (gelegt)", "[liegen] (gelegen)"], ["em pé", "[stellen] (gestellt)", "[stehen] (gestanden)"], ["sentado", "[setzen] / sich setzen", "[sitzen] (gesessen)"], ["pendurado", "[hängen] (gehängt)", "[hängen] (gehangen)"]],
      nota: "Garrafa, copo, livro em pé, móveis → stellen/stehen. Livro deitado, papel, chave, pessoa na cama → legen/liegen."},
    interativo: [{tipo: "troca", estados: [{rotulo: "pôr", de: "Ich [setze] mich auf den Stuhl.", pt: "Eu me sento na cadeira (movimento)."}, {rotulo: "estar", de: "Ich [sitze] auf dem Stuhl.", pt: "Estou sentado na cadeira."}]},
      {tipo: "complete", itens: [["Die Flasche ___ im Kühlschrank. (estar em pé)", "steht", "estar em pé: stehen"], ["Ich ___ die Flasche in den Kühlschrank. (pôr em pé)", "stelle", "pôr em pé: stellen"], ["Der Patient ___ im Bett. (estar deitado)", "liegt", "estar deitado: liegen"], ["___ Sie sich bitte! (sentar-se)", "Setzen", "sich setzen"]]}],
    armadilha: {pt: "Ponho o livro na mesa.", errado: "Ich liege das Buch auf den Tisch.", certo: "Ich lege das Buch auf den Tisch."},
    exemplos: [["Ich [lege] den Schlüssel auf den Tisch. – Er [liegt] auf dem Tisch.", "Ponho a chave na mesa. – Ela está na mesa."], ["Wir [stellen] das Sofa an die Wand.", "Pomos o sofá na parede."], ["Die Kinder [sitzen] im Auto.", "As crianças estão sentadas no carro."]],
    hospital: ["[Legen] Sie sich bitte hin. – Bleiben Sie ruhig [liegen].", "Deite-se, por favor. – Fique deitado tranquilo."],
    conversa: ["O português usa “pôr/colocar” e “estar” para tudo. O alemão ainda diz COMO a coisa fica: deitada (legen/liegen), em pé (stellen/stehen) ou sentada (setzen/sitzen).",
      "Um jeito de lembrar: os de pôr têm “e” (legen, stellen, setzen) e precisam de um objeto; os de estar têm “i/ie” (liegen, sitzen) e são o resultado.",
      "Essa dupla anda junto com as preposições de lugar: pôr → acusativo (auf den Tisch), estar → dativo (auf dem Tisch)."],
    treino: [["Ponho o livro na mesa.", "Ich lege das Buch auf den Tisch."], ["O livro está na mesa.", "Das Buch liegt auf dem Tisch."], ["Ponho a garrafa na geladeira.", "Ich stelle die Flasche in den Kühlschrank."], ["A garrafa está na geladeira.", "Die Flasche steht im Kühlschrank."], ["Sente-se, por favor.", "Setzen Sie sich bitte."], ["Estou sentado na cadeira.", "Ich sitze auf dem Stuhl."], ["O paciente está deitado na cama.", "Der Patient liegt im Bett."], ["Deite-se, por favor.", "Legen Sie sich bitte hin."]],
    erros: [["Ich liege das Handy auf den Tisch.", "Ich lege das Handy auf den Tisch.", "Pôr = legen."], ["Ich setze auf dem Stuhl.", "Ich sitze auf dem Stuhl.", "Estar sentado = sitzen."]]
  });

  add({id: "partikeln", title: "Palavrinhas que dão o tom: denn, mal, doch, ja", short: "Partículas que não mudam o sentido, mas o tom: denn (curiosidade), mal (suaviza o pedido), doch (insistência/estímulo), ja (algo já sabido).",
    body: ["Was machst du denn? (curioso) · Kannst du mal kommen? (pedido leve) · Komm doch mit! (vem, vai!) · Das ist ja toll! (surpresa)."],
    trap: ["Kannst du helfen mir mal?", "Kannst du mir mal helfen?"],
    examples: [["Wie heißt du denn?", "E como você se chama?"], ["Komm doch mit!", "Vem junto, vai!"]],
    detect: c => /\b(denn|mal|doch|ja)\b/.test(low(c).replace(/^ja\b/, "")) && /\?|!|\bja\b/.test(c.frase || "")}, {
    ideia: "Partículas modais são “tempero”: não mudam o que a frase diz, mudam o tom — mais gentil, mais curioso, mais insistente.",
    macete: "MAL = “rapidinho” (pedido leve). DOCH = “vai, anda!” (estímulo). DENN = “e aí?” (curiosidade). JA = “né!” (óbvio ou surpresa).",
    visual: {head: ["partícula", "tom", "exemplo"], rows: [["[mal]", "pedido leve, “rapidinho”", "Kannst du [mal] kommen?"], ["[doch]", "estímulo, insistência", "Setzen Sie sich [doch]!"], ["[denn]", "curiosidade em pergunta", "Was ist [denn] los?"], ["[ja]", "surpresa ou “como sabemos”", "Das ist [ja] super!"], ["[eben] / [halt]", "“é assim mesmo”", "Das ist [halt] so."]],
      nota: "Ficam no meio da frase, normalmente depois do verbo e dos pronomes."},
    interativo: [{tipo: "troca", estados: [{rotulo: "seco", de: "Kommen Sie herein.", pt: "Entre. (neutro)"}, {rotulo: "acolhedor", de: "Kommen Sie [doch] herein!", pt: "Entre, por favor, fique à vontade!"}]},
      {tipo: "revelar", itens: [["O que houve? (curioso)", "Was ist denn los?"], ["Me ajuda rapidinho?", "Kannst du mir mal helfen?"], ["Vem junto, vai!", "Komm doch mit!"], ["Isso é ótimo!", "Das ist ja super!"]]}],
    armadilha: {pt: "Me ajuda rapidinho?", errado: "Kannst du helfen mir mal?", certo: "Kannst du mir mal helfen?"},
    exemplos: [["Was machst du [denn] hier?", "E o que você está fazendo aqui?"], ["Schau [mal]!", "Olha só!"], ["Du bist [ja] schon da!", "Você já chegou!"]],
    hospital: ["Erzählen Sie [mal], was passiert ist.", "Me conte o que aconteceu."],
    conversa: ["Sem essas palavrinhas o alemão soa seco e mandão; com elas, natural e simpático. “Erzählen Sie mal” abre uma anamnese de forma bem mais acolhedora que “Erzählen Sie”.",
      "Você não precisa usá-las desde o começo, mas precisa reconhecê-las: aparecem em quase toda conversa real.",
      "O denn da pergunta não é o denn de “porque”: aqui ele só mostra interesse (“Wie geht's dir denn?”)."],
    treino: [["O que houve?", "Was ist denn los?"], ["Me ajuda rapidinho?", "Kannst du mir mal helfen?"], ["Vem junto, vai!", "Komm doch mit!"], ["Olha só!", "Schau mal!"], ["Me conte o que aconteceu.", "Erzählen Sie mal, was passiert ist."], ["Isso é ótimo!", "Das ist ja super!"], ["Sente-se, por favor!", "Setzen Sie sich doch!"], ["É assim mesmo.", "Das ist halt so."]],
    erros: [["Kannst du helfen mir mal?", "Kannst du mir mal helfen?", "Pronome e mal no meio, verbo no fim."]]
  });

  add({id: "zeitpraep", title: "Há, daqui a, a partir de: seit, vor, in, ab, für", short: "seit = há (e continua); vor = há (já acabou); in = daqui a; ab = a partir de; für = por (duração planejada). Todas com dativo, menos für (acusativo).",
    body: ["Ich wohne seit zwei Jahren hier (moro há dois anos, ainda moro). Ich bin vor zwei Jahren umgezogen (mudei há dois anos). In zwei Wochen fliege ich (daqui a duas semanas). Ab Montag arbeite ich (a partir de segunda). Ich fahre für eine Woche (por uma semana)."],
    trap: ["Ich wohne hier vor zwei Jahren.", "Ich wohne hier seit zwei Jahren."],
    examples: [["Seit wann haben Sie Fieber?", "Desde quando o senhor tem febre?"], ["Vor einer Woche war ich krank.", "Há uma semana eu estava doente."]],
    detect: c => /\b(seit (einem|einer|zwei|drei|vier|fünf|ein paar|wann|gestern|heute|kurzem)|vor (einem|einer|zwei|drei|vier|fünf|ein paar|kurzem) (tag|tagen|woche|wochen|monat|monaten|jahr|jahren|stunde|stunden|minuten)|in (einer|zwei|drei) (woche|wochen|stunde|stunden|tagen|monaten)|ab (montag|morgen|nächste|heute|sofort))\b/.test(low(c))}, {
    ideia: "Para falar de tempo, cada “há” do português vira uma palavra diferente: se ainda dura, seit; se já acabou, vor. E “daqui a” é in.",
    macete: "SEIT = começou e CONTINUA (verbo no presente!). VOR = aconteceu e ACABOU (verbo no passado). IN = no futuro. Todas + dativo: seit zwei Jahre[n].",
    visual: {head: ["palavra", "sentido", "exemplo"], rows: [["[seit] + dat.", "há (e continua)", "Ich habe [seit] drei Tag[en] Husten."], ["[vor] + dat.", "há (já passou)", "Ich war [vor] drei Tag[en] beim Arzt."], ["[in] + dat.", "daqui a", "[In] zwei Woch[en] fliege ich."], ["[ab] + dat.", "a partir de", "[Ab] Montag habe ich Urlaub."], ["[für] + acus.", "por (duração planejada)", "Ich fahre [für] eine Woche weg."]],
      nota: "Plural no dativo ganha -n: seit zwei Jahren, vor drei Tagen, in zwei Wochen."},
    interativo: [{tipo: "troca", estados: [{rotulo: "ainda dura", de: "Ich habe [seit] zwei Tagen Fieber.", pt: "Tenho febre há dois dias (e ainda tenho)."}, {rotulo: "já acabou", de: "Ich hatte [vor] zwei Tagen Fieber.", pt: "Tive febre há dois dias."}, {rotulo: "futuro", de: "Ich fliege [in] zwei Tagen.", pt: "Viajo daqui a dois dias."}]},
      {tipo: "complete", itens: [["Ich wohne ___ zwei Jahren in Curitiba. (há, ainda moro)", "seit", "continua → seit"], ["Ich bin ___ zwei Jahren umgezogen. (há, já foi)", "vor", "acabou → vor"], ["___ drei Wochen habe ich Urlaub. (daqui a)", "In", "futuro → in"], ["Ich habe seit drei ___ Husten. (Tag, plural)", "Tagen", "dativo plural -n"]]}],
    armadilha: {pt: "Moro aqui há dois anos.", errado: "Ich wohne hier vor zwei Jahren.", certo: "Ich wohne hier seit zwei Jahren."},
    exemplos: [["Ich arbeite [seit] 2021 als Arzt.", "Trabalho como médico desde 2021."], ["[Vor] einem Monat war ich in Ponta Grossa.", "Há um mês estive em Ponta Grossa."], ["[In] einer Stunde beginnt mein Dienst.", "Daqui a uma hora começa meu plantão."]],
    hospital: ["[Seit] wann haben Sie die Beschwerden? – [Seit] drei Tagen.", "Desde quando o senhor tem as queixas? – Há três dias."],
    conversa: ["O “há” do português esconde duas ideias que o alemão separa. Se a coisa ainda está acontecendo, seit — e o verbo fica no PRESENTE (“Ich habe seit drei Tagen Fieber”). Se já terminou, vor + passado.",
      "Na anamnese, seit é a palavra do dia: “Seit wann?”, “Seit gestern”, “Seit einer Woche”.",
      "in + tempo é sempre futuro: “in zwei Wochen” = daqui a duas semanas (não “em duas semanas” no sentido de duração)."],
    treino: [["Moro aqui há dois anos.", "Ich wohne hier seit zwei Jahren."], ["Mudei há dois anos.", "Ich bin vor zwei Jahren umgezogen."], ["Daqui a duas semanas eu viajo.", "In zwei Wochen fliege ich."], ["A partir de segunda tenho férias.", "Ab Montag habe ich Urlaub."], ["Tenho tosse há três dias.", "Ich habe seit drei Tagen Husten."], ["Trabalho como médico desde 2021.", "Ich arbeite seit 2021 als Arzt."], ["Vou viajar por uma semana.", "Ich fahre für eine Woche weg."], ["Desde quando o senhor tem dor?", "Seit wann haben Sie Schmerzen?"]],
    erros: [["Ich habe Fieber vor drei Tagen.", "Ich habe seit drei Tagen Fieber.", "Ainda tem febre → seit + presente."], ["Ich wohne seit zwei Jahre hier.", "Ich wohne seit zwei Jahren hier.", "Dativo plural ganha -n."]]
  });

  add({id: "wortbildung", title: "Palavras compostas e terminações (-ung, -er, -heit)", short: "Em palavras compostas, a última parte manda (sentido e artigo): der Kopf + die Schmerzen = die Kopfschmerzen. -ung, -heit, -keit → die; -er (quem faz) → der.",
    body: ["Leia de trás para frente: Krankenhaus = Haus (casa) dos Kranken (doentes) = hospital. O artigo é o da última palavra: das Haus → das Krankenhaus.",
      "Verbo + -ung vira substantivo feminino: untersuchen → die Untersuchung. Verbo + -er vira quem faz: backen → der Bäcker."],
    trap: ["der Krankenhaus", "das Krankenhaus"],
    examples: [["Ich habe Kopfschmerzen.", "Tenho dor de cabeça."], ["Die Untersuchung dauert zehn Minuten.", "O exame dura dez minutos."]],
    detect: c => /\b\w+(ung|heit|keit|schaft)\b/.test(low(c)) || /\b(krankenhaus|kopfschmerzen|bauchschmerzen|rückenschmerzen|hausarzt|notaufnahme|blutdruck)\b/.test(low(c))}, {
    ideia: "Palavras alemãs longas são peças de Lego: leia de trás para frente. A ÚLTIMA peça diz o que a coisa é — e dá o artigo.",
    macete: "Krankenhaus = Haus (casa) + Kranken (dos doentes). Última peça manda: das Haus → das Krankenhaus. -ung/-heit/-keit = die; quem faz (-er) = der.",
    visual: {head: ["palavra", "peças (de trás para frente)", "artigo"], rows: [["Krankenhaus", "Haus ← kranken", "[das] (das Haus)"], ["Kopfschmerzen", "Schmerzen ← Kopf", "[die] (plural)"], ["Blutdruck", "Druck (pressão) ← Blut", "[der] (der Druck)"], ["Notaufnahme", "Aufnahme (admissão) ← Not (urgência)", "[die]"], ["untersuchen → Untersuch[ung]", "verbo + -ung", "[die]"], ["backen → Bäck[er]", "verbo + -er (quem faz)", "[der]"], ["krank → Krank[heit]", "adjetivo + -heit", "[die]"]],
      nota: "Às vezes entra um “elo”: -s- (Geburtstag), -n- (Krankenhaus), -e- (Wartezimmer). Ele não muda nada."},
    interativo: [{tipo: "revelar", itens: [["a sala de espera (warten + Zimmer)", "das Wartezimmer"], ["o médico de família (Haus + Arzt)", "der Hausarzt"], ["a dor de barriga (Bauch + Schmerzen)", "die Bauchschmerzen"], ["a coleta de sangue (Blut + Abnahme)", "die Blutabnahme"]]},
      {tipo: "complete", itens: [["untersuchen → die Untersuch___", "ung", "verbo + -ung"], ["___ Krankenhaus (artigo)", "das", "última peça: das Haus"], ["krank → die Krank___", "heit", "adjetivo + -heit"]]}],
    armadilha: {pt: "o hospital", errado: "der Krankenhaus", certo: "das Krankenhaus"},
    exemplos: [["Ich habe [Kopf]schmerzen.", "Tenho dor de cabeça."], ["Die Untersuch[ung] dauert zehn Minuten.", "O exame dura dez minutos."], ["Mein [Haus]arzt ist im Urlaub.", "Meu médico de família está de férias."]],
    hospital: ["Bitte nehmen Sie im [Warte]zimmer Platz.", "Por favor, aguarde na sala de espera."],
    conversa: ["O alemão não cria palavras novas: junta as que já tem. Quem sabe as peças lê palavras gigantes sem dicionário: Herzinfarkt (coração + infarto), Lungenentzündung (pulmão + inflamação = pneumonia).",
      "A regra de ouro: a última peça é a principal — o resto só especifica. Por isso o artigo também vem dela.",
      "Terminações transformam: verbo + -ung = a ação como substantivo (behandeln → Behandlung, tratamento), sempre feminino."],
    treino: [["o hospital", "das Krankenhaus"], ["Tenho dor de cabeça.", "Ich habe Kopfschmerzen."], ["O exame dura dez minutos.", "Die Untersuchung dauert zehn Minuten."], ["a sala de espera", "das Wartezimmer"], ["Meu médico de família está de férias.", "Mein Hausarzt ist im Urlaub."], ["a pressão arterial", "der Blutdruck"], ["o tratamento", "die Behandlung"], ["a pneumonia", "die Lungenentzündung"]],
    erros: [["der Krankenhaus", "das Krankenhaus", "A última peça manda: das Haus."], ["das Untersuchung", "die Untersuchung", "-ung é sempre die."]]
  });

  add({id: "demonstr", title: "dieser, welcher, jeder", short: "dieser (este), welcher? (qual?), jeder (cada) mudam como der/die/das: dieser Arzt, diese Ärztin, dieses Kind; welchen Termin?",
    body: ["As terminações seguem o artigo definido: der → dieser/welcher/jeder, den → diesen, dem → diesem, die → diese, das → dieses.",
      "jeder só no singular; no plural use alle."],
    trap: ["Welche Termin passt Ihnen?", "Welcher Termin passt Ihnen?"],
    examples: [["Dieser Termin passt mir gut.", "Esta consulta me serve bem."], ["Welches Medikament nehmen Sie?", "Qual remédio o senhor toma?"]],
    detect: c => /\b(dieser|diese|dieses|diesen|diesem|welcher|welche|welches|welchen|welchem|jeder|jede|jedes|jeden|jedem)\b/.test(low(c))}, {
    ideia: "dieser (este), welcher? (qual?) e jeder (cada) usam as mesmas terminações do der/die/das — a última letra do artigo vira a terminação.",
    macete: "Copie a última letra do artigo: deR → diese[r], diE → diese, daS → diese[s], deN → diese[n], deM → diese[m].",
    visual: {head: ["artigo", "dieser", "welcher?", "jeder"], rows: [["der (nom.)", "diese[r] Arzt", "welche[r] Arzt?", "jede[r] Arzt"], ["die", "diese Ärztin", "welche Ärztin?", "jede Ärztin"], ["das", "diese[s] Kind", "welche[s] Kind?", "jede[s] Kind"], ["den (acus.)", "diese[n] Termin", "welche[n] Termin?", "jede[n] Tag"], ["dem (dat.)", "diese[m] Arzt", "welche[m] Arzt?", "jede[m] Patienten"]],
      nota: "jeden Tag = todo dia (acusativo de tempo). Plural de jeder: alle."},
    interativo: [{tipo: "complete", itens: [["___ Medikament nehmen Sie? (qual, das)", "Welches", "das → -es"], ["Ich nehme ___ Tablette. (esta, die)", "diese", "die → -e"], ["Ich trinke ___ Tag Kaffee. (todo, der Tag)", "jeden", "acusativo → -en"], ["Mit ___ Bus fahren Sie? (qual, dativo)", "welchem", "dem → -em"]]}],
    armadilha: {pt: "Qual consulta serve para o senhor?", errado: "Welche Termin passt Ihnen?", certo: "Welcher Termin passt Ihnen?"},
    exemplos: [["[Dieser] Termin passt mir gut.", "Esta consulta me serve bem."], ["[Welches] Medikament nehmen Sie?", "Qual remédio o senhor toma?"], ["Ich trinke [jeden] Tag zwei Liter Wasser.", "Bebo dois litros de água todo dia."]],
    hospital: ["[Welche] Medikamente nehmen Sie [jeden] Tag?", "Quais remédios o senhor toma todo dia?"],
    conversa: ["Se você já sabe der/die/das/den/dem, não precisa decorar nada novo: dieser, welcher e jeder copiam a última letra do artigo.",
      "welcher é a pergunta “qual?” quando há opções: “Welcher Bus fährt zum Bahnhof?”. Para “o quê?” sem opções, use was.",
      "jeden Tag, jede Woche, jedes Jahr = todo dia, toda semana, todo ano."],
    treino: [["Esta consulta me serve.", "Dieser Termin passt mir."], ["Qual remédio o senhor toma?", "Welches Medikament nehmen Sie?"], ["Bebo água todo dia.", "Ich trinke jeden Tag Wasser."], ["Quais remédios o senhor toma?", "Welche Medikamente nehmen Sie?"], ["Este paciente está melhor.", "Diesem Patienten geht es besser."], ["Qual ônibus vai para a estação?", "Welcher Bus fährt zum Bahnhof?"], ["Toda semana tenho dois plantões.", "Jede Woche habe ich zwei Dienste."]],
    erros: [["Welche Bus fährt zum Bahnhof?", "Welcher Bus fährt zum Bahnhof?", "der Bus → welcher."], ["Ich trinke jede Tag Kaffee.", "Ich trinke jeden Tag Kaffee.", "der Tag no acusativo → jeden."]]
  });
})();
